<script setup lang="ts">
import axios from 'axios';
import { computed,onMounted,onUnmounted,ref,useId,watch } from 'vue';
import { api,errorMessage } from '../api';
import { amount } from '../catalog';
import { readPending,savePending,clearPending } from '../lib/pendingRequests';
import { downloadPrivatePdf } from '../lib/downloadPdf';
import { weeklyPeriodStart } from '../lib/weeklyPeriod';
import type { Business,Store } from '../types';
import type { SalesCustomer } from '../sales';
import AppDialog from './AppDialog.vue';
import SalesCustomers from './SalesCustomers.vue';
type Member={id:number;number:string|number;version:number;status:string;included:boolean;total:string;paid:string;pending:string;invoice_id:number|null};
type Account={id:number;customer_id:number;customer_name:string;period_start:string;period_end:string;timezone:string;currency:string;status:string;lock_version:number;review_hash:string;orders:Member[];totals:{grand_total:string;paid_total:string;pending_total:string;net_total?:string;return_credit_total?:string;credit_available?:string;refunded_total?:string};invoice:{id:number;invoice_number:string;status:string}|null;return_pending?:boolean};
type Candidate={id:number;number:string|number;total:string;currency:string};
type Operation={kind:'create'|'attach'|'detach'|'close'|'cancel';accountId?:number;payload:Record<string,unknown>&{request_key:string}};
const props=defineProps<{store?:Store;business:Business;actorId:number;permissions:string[]}>();
const emit=defineEmits<{openOrder:[number];'context-locked':[boolean]}>();
const root=`/business/stores/${props.store?.id}`;const endpoint=root+'/weekly-accounts';const journal=`bshop:weekly:${props.actorId}:${props.store?.id}`;
const accounts=ref<Account[]>([]);const selected=ref<Account|null>(null);const candidates=ref<Candidate[]>([]);const status=ref('open');const page=ref(1);const lastPage=ref(1);const dueCount=ref(0);const candidatePage=ref(1);const candidateLast=ref(1);
const error=ref('');const sessionExpired=ref(false);const notice=ref('');const busy=ref(false);const loading=ref(false);const pending=ref<Operation|null>(null);const modal=ref<'create'|'close'|null>(null);const customer=ref<SalesCustomer|null>(null);const start=ref('');const opener=ref<HTMLElement|null>(null);const formId=useId();
const manage=computed(()=>props.permissions.includes('sales.create'));const locked=computed(()=>busy.value||!!pending.value);let alive=true;let listToken=0;let detailToken=0;
const closeWeekday=ref<number|null>(null);const policyLoading=ref(true);
function clearError(){error.value='';sessionExpired.value=false;}
function setError(e:unknown){sessionExpired.value=axios.isAxiosError(e)&&e.response?.status===401;error.value=errorMessage(e);}
watch(locked,value=>emit('context-locked',value),{immediate:true});
async function load(target=1){const token=++listToken;loading.value=true;try{const result=await api.get(endpoint,{params:{status:status.value,page:target}});if(alive&&token===listToken){accounts.value=result.data.data;page.value=result.data.meta.current_page;lastPage.value=result.data.meta.last_page;dueCount.value=result.data.meta.due_count??0;clearError();}}catch(e){if(alive&&token===listToken)setError(e);}finally{if(alive&&token===listToken)loading.value=false;}}
async function loadCandidates(target=1){if(!selected.value||selected.value.status!=='open'){candidates.value=[];return;}const token=detailToken;const id=selected.value.id;try{const result=await api.get(`${endpoint}/${id}/candidates`,{params:{page:target}});if(alive&&token===detailToken&&selected.value?.id===id){candidates.value=result.data.data;candidatePage.value=result.data.meta.current_page;candidateLast.value=result.data.meta.last_page;}}catch(e){if(alive&&token===detailToken)setError(e);}}
async function select(id:number){if(locked.value)return;const token=++detailToken;busy.value=true;clearError();try{const result=await api.get(`${endpoint}/${id}`);if(alive&&token===detailToken){selected.value=result.data.data;await loadCandidates();}}catch(e){if(alive)setError(e);}finally{if(alive)busy.value=false;}}
function openCreate(event:Event){opener.value=event.currentTarget as HTMLElement;modal.value='create';customer.value=null;start.value=weeklyPeriodStart(props.business.timezone,closeWeekday.value);clearError();}
function review(event:Event){opener.value=event.currentTarget as HTMLElement;modal.value='close';clearError();}
async function finish(account:Account,recovered=false){if(!alive)return;pending.value=null;selected.value=account;modal.value=null;clearError();notice.value=recovered?'Operación recuperada sin repetir cambios.':account.status==='closed'?'Cuenta cerrada y factura generada.':account.status==='cancelled'?'Cuenta vacía anulada.':'Cuenta actualizada.';try{clearPending(journal);}catch{}if(account.status!=='open')status.value='all';await load(page.value);await loadCandidates();}
function url(operation:Operation){return operation.kind==='create'?endpoint:['close','cancel'].includes(operation.kind)?`${endpoint}/${operation.accountId}/${operation.kind}`:`${endpoint}/${operation.accountId}/orders/${operation.kind}`;}
async function send(operation?:Operation){
    if(busy.value||!manage.value)return;clearError();notice.value='';
    if(!pending.value){if(!operation)return;try{savePending(journal,operation as unknown as Record<string,unknown>);pending.value=operation;}catch{error.value='No se pudo guardar la recuperación. No se enviaron cambios.';return;}}
    busy.value=true;try{const result=(await api.post(url(pending.value),pending.value.payload)).data.data;if(alive){await finish(result.account);if(result.document?.status==='failed')notice.value='La factura está emitida; reintenta preparar su PDF sin volver a cerrar.';}}
    catch(e){if(alive){setError(e);modal.value=null;if(axios.isAxiosError(e)&&e.response&&[409,422].includes(e.response.status)){pending.value=null;try{clearPending(journal);}catch{}}}}
    finally{if(alive)busy.value=false;}
}
function create(){if(customer.value)send({kind:'create',payload:{request_key:crypto.randomUUID(),customer_id:customer.value.id,period_start:start.value}});}
function membership(order:number,kind:'attach'|'detach'){if(selected.value)send({kind,accountId:selected.value.id,payload:{request_key:crypto.randomUUID(),version:selected.value.lock_version,order_id:order}});}
function close(){if(selected.value)send({kind:'close',accountId:selected.value.id,payload:{request_key:crypto.randomUUID(),version:selected.value.lock_version,review_hash:selected.value.review_hash}});}
function cancel(){if(selected.value)send({kind:'cancel',accountId:selected.value.id,payload:{request_key:crypto.randomUUID(),version:selected.value.lock_version}});}
async function recover(){if(!pending.value||busy.value)return;busy.value=true;clearError();try{const result=(await api.get(`${endpoint}/requests/${pending.value.payload.request_key}`,{params:{operation:pending.value.kind}})).data.data;await finish(result.account,true);}catch(e){if(alive){if(axios.isAxiosError(e)&&e.response?.status===404){clearError();error.value='La operación no está confirmada. Reintenta los mismos datos.';}else setError(e);}}finally{if(alive)busy.value=false;}}
async function pdf(){if(!selected.value?.invoice||locked.value)return;busy.value=true;clearError();try{const invoice=selected.value.invoice;const result=await api.post(`${root}/invoices/${invoice.id}/document`);await downloadPrivatePdf(result.data.data.url,invoice.invoice_number+'.pdf');}catch(e){if(alive)setError(e);}finally{if(alive)busy.value=false;}}
watch(status,()=>load());
onMounted(async()=>{void api.get('/business/weekly/settings').then(({data})=>{if(alive&&Number.isInteger(data.data.close_weekday)&&data.data.close_weekday>=1&&data.data.close_weekday<=7)closeWeekday.value=data.data.close_weekday;}).catch(()=>{}).finally(()=>{if(alive)policyLoading.value=false;});await load();const saved=readPending(journal) as unknown as Operation|null;if(saved&&['create','attach','detach','close','cancel'].includes(saved.kind)&&typeof saved.payload?.request_key==='string'){pending.value=saved;await recover();}});
onUnmounted(()=>{alive=false;++listToken;++detailToken;emit('context-locked',false);});
</script>
<template><div class="weekly-workspace">
    <div v-if="error&&!modal" class="notice error" role="alert"><span>{{ error }}</span> <a v-if="sessionExpired" class="button secondary" href="/login">Ir a iniciar sesión</a></div><p v-if="notice" class="notice success" role="status">{{ notice }}</p>
    <div v-if="pending" class="notice" role="status">Hay una operación sin confirmar. <button type="button" class="button secondary" :disabled="busy" @click="recover">Comprobar operación semanal</button><button v-if="manage" type="button" class="button secondary" :disabled="busy" @click="send()">Reintentar misma operación</button></div>
    <section class="panel" aria-label="Cuentas semanales"><div class="panel-heading"><div><h2>Cuentas semanales</h2><p class="muted">Agrupa apartados de un cliente durante siete días y revisa el cierre antes de facturar.</p></div><button v-if="manage" type="button" class="button primary" :disabled="locked||policyLoading" @click="openCreate">Nueva cuenta semanal</button></div><div v-if="dueCount>0" class="notice" role="status"><span>{{ dueCount }} {{ dueCount===1?'cuenta llegó':'cuentas llegaron' }} a su día de corte y {{ dueCount===1?'requiere':'requieren' }} revisión. No se ha facturado automáticamente.</span> <button type="button" class="button secondary" :disabled="locked||loading" @click="status='due'">Ver cuentas por revisar</button></div><label>Estado de cuentas<select v-model="status" :disabled="locked"><option value="open">Abiertas</option><option value="due">Por revisar</option><option value="closed">Cerradas</option><option value="all">Todas</option></select></label><p v-if="loading" role="status">Consultando cuentas…</p>
    <div class="weekly-list"><button v-for="account in accounts" :key="account.id" type="button" class="weekly-card" :aria-pressed="selected?.id===account.id" :disabled="locked" @click="select(account.id)"><strong>{{ account.customer_name }} · #{{ account.id }}</strong><span>{{ account.period_start }} al {{ account.period_end }}</span><span>{{ account.status==='closed'?'Cerrada':account.status==='cancelled'?'Anulada':'Abierta' }} · {{ amount(account.totals.grand_total,account.currency) }}</span></button></div><p v-if="!loading&&!error&&!accounts.length" class="muted">No hay cuentas con este filtro.</p><div v-if="lastPage>1" class="catalog-pagination"><button type="button" class="button secondary" :disabled="locked||loading||page<=1" @click="load(page-1)">Anterior</button><span>{{ page }}/{{ lastPage }}</span><button type="button" class="button secondary" :disabled="locked||loading||page>=lastPage" @click="load(page+1)">Siguiente</button></div>
    <button type="button" class="button secondary" :disabled="locked||loading" @click="load(page)">Actualizar cuentas</button></section>
    <section v-if="selected" class="panel" aria-label="Detalle de cuenta semanal"><div class="panel-heading"><div><h2>{{ selected.customer_name }} · Cuenta #{{ selected.id }}</h2><p>{{ selected.period_start }} al {{ selected.period_end }} · {{ selected.timezone }}</p></div><button type="button" class="button secondary" :disabled="locked" @click="select(selected.id)">Actualizar revisión</button></div>
        <p v-if="selected.return_pending" class="notice">Hay mercancía devuelta con ajuste económico pendiente. Los importes originales están por conciliar y la factura tiene el cobro bloqueado.</p>
        <p v-if="selected.totals.return_credit_total&&selected.totals.return_credit_total!=='0.0000'" class="notice">Original {{ amount(selected.totals.grand_total,selected.currency) }} · Ajuste {{ amount(selected.totals.return_credit_total,selected.currency) }} · Saldo a favor {{ amount(selected.totals.credit_available,selected.currency) }} · Reembolsado {{ amount(selected.totals.refunded_total,selected.currency) }}</p>
        <dl class="weekly-totals"><div><dt>Total neto agrupado</dt><dd>{{ amount(selected.totals.net_total??selected.totals.grand_total,selected.currency) }}</dd></div><div><dt>Abonado</dt><dd>{{ amount(selected.totals.paid_total,selected.currency) }}</dd></div><div><dt>Pendiente</dt><dd>{{ amount(selected.totals.pending_total,selected.currency) }}</dd></div></dl>
        <article v-for="order in selected.orders" :key="order.id" class="weekly-order"><div><strong>Apartado #{{ order.number }}</strong><p>{{ amount(order.total,selected.currency) }} · Abonado {{ amount(order.paid,selected.currency) }}</p><p v-if="!order.included" class="notice">Excluido del cierre: cancelado o facturado individualmente.</p></div><div class="actions"><button type="button" class="button secondary" :disabled="locked" @click="emit('openOrder',order.id)">Ver apartado #{{ order.number }}</button><button v-if="manage&&selected.status==='open'" type="button" class="button secondary" :disabled="locked" :aria-label="`Quitar de la cuenta #${order.number}`" @click="membership(order.id,'detach')">Quitar de cuenta</button></div></article>
        <template v-if="selected.status==='open'"><h3>Apartados disponibles para este período</h3><p class="muted">Sólo el mismo cliente, sucursal y moneda; sin factura ni otra cuenta.</p><article v-for="order in candidates" :key="order.id" class="weekly-order"><span>Apartado #{{ order.number }} · {{ amount(order.total,order.currency) }}</span><button v-if="manage" type="button" class="button secondary" :disabled="locked" :aria-label="`Agregar apartado #${order.number}`" @click="membership(order.id,'attach')">Agregar a cuenta</button></article><p v-if="!candidates.length" class="muted">No hay apartados elegibles disponibles.</p><div v-if="candidateLast>1" class="catalog-pagination"><button type="button" class="button secondary" :disabled="locked||candidatePage<=1" @click="loadCandidates(candidatePage-1)">Disponibles anteriores</button><span>{{ candidatePage }}/{{ candidateLast }}</span><button type="button" class="button secondary" :disabled="locked||candidatePage>=candidateLast" @click="loadCandidates(candidatePage+1)">Disponibles siguientes</button></div><button v-if="manage&&permissions.includes('invoices.view')" type="button" class="button primary" :disabled="locked||!selected.orders.some(o=>o.included)" @click="review">Revisar cierre semanal</button></template>
        <button v-if="manage&&selected.status==='open'&&!selected.orders.length" type="button" class="button secondary" :disabled="locked" @click="cancel">Anular cuenta vacía</button>
        <p v-if="selected.status==='cancelled'" class="notice">Cuenta anulada. El historial se conserva.</p>
        <div v-if="selected.invoice" class="notice"><strong>{{ selected.invoice.invoice_number }}</strong><p>Factura única de la cuenta. Los abonos posteriores actualizan su saldo.</p><button v-if="permissions.includes('invoices.view')" type="button" class="button primary" :disabled="locked" @click="pdf">Descargar factura semanal</button></div>
    </section>
    <AppDialog :open="modal==='create'" title="Nueva cuenta semanal" :busy="busy||!!pending" :return-focus="opener" @close="modal=null"><p v-if="error" class="notice error" role="alert">{{ error }}</p><SalesCustomers :root="root" :actor-id="actorId" :selected="customer" :manage="false" :can-summary="false" :currency="business.default_currency" @select="customer=$event"/><form :id="formId" @submit.prevent="create"><label>Inicio de la semana<input v-model="start" type="date" required :disabled="locked"></label><p class="muted">Período de siete días, incluido el día inicial, en {{ business.timezone }}. El cierre será manual.</p><p v-if="policyLoading" class="muted">Consultando el día de corte; puedes elegir la fecha manualmente.</p><p v-else-if="closeWeekday===null" class="notice">No se pudo consultar el día de corte. Selecciona la fecha inicial manualmente.</p><p v-else class="muted">La fecha sugerida corresponde al día de corte configurado; puedes cambiarla.</p></form><template #footer><button type="button" class="button secondary" :disabled="busy" @click="modal=null">Cancelar</button><button type="submit" :form="formId" class="button primary" :disabled="locked||!customer||!start">Crear cuenta semanal</button></template></AppDialog>
    <AppDialog :open="modal==='close'" title="Confirmar cierre semanal" :busy="busy||!!pending" :return-focus="opener" @close="modal=null"><p v-if="error" class="notice error" role="alert">{{ error }}</p><template v-if="selected"><p>Se emitirá una factura única para los {{ selected.orders.filter(o=>o.included).length }} pedidos incluidos. Se conservarán sus reservas y se asignarán sus abonos sin cobrarlos otra vez.</p><p><strong>Total {{ amount(selected.totals.grand_total,selected.currency) }}</strong></p><p>Abonado {{ amount(selected.totals.paid_total,selected.currency) }} · Pendiente {{ amount(selected.totals.pending_total,selected.currency) }}</p><p>Los pedidos facturados individualmente y cancelados quedan fuera.</p></template><template #footer><button type="button" class="button secondary" :disabled="busy" @click="modal=null">Volver</button><button type="button" class="button primary" :disabled="locked" @click="close">Cerrar cuenta y facturar</button></template></AppDialog>
</div></template>
<style scoped>.weekly-workspace{display:grid;gap:24px}.weekly-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr));gap:14px;margin:20px 0}.weekly-card{display:grid;gap:8px;min-height:120px;padding:18px;border:1px solid #ddd5ec;border-radius:14px;background:white;text-align:left;min-width:0;overflow-wrap:anywhere}.weekly-card[aria-pressed=true]{border-color:#7050ca;background:#f4efff}.weekly-order{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid #e7e0ef}.weekly-order>div{min-width:0;overflow-wrap:anywhere}.weekly-order .actions{flex-wrap:wrap}.weekly-totals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}.weekly-totals>div{min-width:0;background:#f5f1fc;padding:16px;border-radius:12px}.weekly-totals dd{margin:8px 0 0;font-weight:750;font-size:20px;overflow-wrap:anywhere}.weekly-workspace h3{margin:24px 0 12px}@media(max-width:767px){.weekly-order{align-items:stretch;flex-direction:column}.weekly-totals{grid-template-columns:minmax(0,1fr)}.weekly-order .actions{display:grid;grid-template-columns:minmax(0,1fr)}}</style>
